INSERT OR IGNORE INTO posts (id, slug, title, subtitle, excerpt, body_md, body_html, status, visibility, author_id, cover_key, cover_alt, word_count, reading_minutes, created_at, updated_at, published_at, scheduled_for) VALUES ('p3', 'd1-as-a-content-store', 'D1 as a content store: what worked, what surprised me', 'SQLite at the edge, holding actual prose', 'A blog is a small dataset with a demanding read pattern: a handful of queries, run constantly, that must be fast everywhere. That is a good fit for D1, with a few things worth knowing up…', 'A blog is a small dataset with a demanding read pattern: a handful of
queries, run constantly, that must be fast everywhere. That is a good fit for D1, with a
few things worth knowing up front.

## Markdown is the source of truth, HTML is a cache

Every post stores both `body_md` and `body_html`. Rendering happens once, on write.

The temptation is to render on read and keep one column. Don''t. Rendering on read puts a
Markdown parser on the hot path of every page view to produce a byte-identical result
every time. Rendering on write means a public read is one indexed `SELECT` and a
serialisation, and a change to the renderer becomes a migration — which is the right
place for it, because you want to know exactly when every post''s HTML changed.

## Store timestamps as ISO-8601 strings

Not epoch integers. They sort lexicographically, they are unambiguous about timezone, and
when you are staring at the D1 console at 2am trying to work out why a scheduled post did
not go out, you can read them.

## Set `published_at` exactly once

Editing a published post touches `updated_at` and nothing else. Unpublishing and
republishing does not reset it either. Otherwise a typo fix silently moves a two-year-old
post to the top of the feed and into every subscriber''s reader.

## The scheduled-publish query is free

```sql
CREATE INDEX idx_posts_scheduled ON posts(status, scheduled_for)
  WHERE status = ''scheduled'';
```

A partial index over the handful of scheduled rows. The cron trigger runs every five
minutes and the query touches almost nothing.

## What surprised me

Full-text search. `fts5` is available and works, but keeping the external-content table
in sync through triggers is more machinery than a personal blog needs. `LIKE` over title
and excerpt is genuinely fine below a few thousand posts, and you can add FTS the day
that stops being true.', '<p>A blog is a small dataset with a demanding read pattern: a handful of
queries, run constantly, that must be fast everywhere. That is a good fit for D1, with a
few things worth knowing up front.</p>
<h2 id="markdown-is-the-source-of-truth-html-is-a-cache">Markdown is the source of truth, HTML is a cache</h2>
<p>Every post stores both <code>body_md</code> and <code>body_html</code>. Rendering happens once, on write.</p>
<p>The temptation is to render on read and keep one column. Don&#39;t. Rendering on read puts a
Markdown parser on the hot path of every page view to produce a byte-identical result
every time. Rendering on write means a public read is one indexed <code>SELECT</code> and a
serialisation, and a change to the renderer becomes a migration — which is the right
place for it, because you want to know exactly when every post&#39;s HTML changed.</p>
<h2 id="store-timestamps-as-iso-8601-strings">Store timestamps as ISO-8601 strings</h2>
<p>Not epoch integers. They sort lexicographically, they are unambiguous about timezone, and
when you are staring at the D1 console at 2am trying to work out why a scheduled post did
not go out, you can read them.</p>
<h2 id="set-publishedat-exactly-once">Set <code>published_at</code> exactly once</h2>
<p>Editing a published post touches <code>updated_at</code> and nothing else. Unpublishing and
republishing does not reset it either. Otherwise a typo fix silently moves a two-year-old
post to the top of the feed and into every subscriber&#39;s reader.</p>
<h2 id="the-scheduled-publish-query-is-free">The scheduled-publish query is free</h2>
<pre><code class="language-sql">CREATE INDEX idx_posts_scheduled ON posts(status, scheduled_for)
  WHERE status = &#39;scheduled&#39;;</code></pre>
<p>A partial index over the handful of scheduled rows. The cron trigger runs every five
minutes and the query touches almost nothing.</p>
<h2 id="what-surprised-me">What surprised me</h2>
<p>Full-text search. <code>fts5</code> is available and works, but keeping the external-content table
in sync through triggers is more machinery than a personal blog needs. <code>LIKE</code> over title
and excerpt is genuinely fine below a few thousand posts, and you can add FTS the day
that stops being true.</p>', 'published', 'public', 'a2', NULL, NULL, 291, 2, '2026-07-06T16:40:00Z', '2026-07-06T16:40:00Z', '2026-07-04T08:15:00Z', NULL);
